def minimum_swaps_to_sort(N, M, permutation, allowed_swaps):
    from collections import deque

    def perm_to_tuple(perm):
        return tuple(perm)

    def get_neighbors(perm):
        neighbors = []
        for i in range(N):
            for j in range(i + 1, N):
                if (i + 1, j + 1) in allowed_swaps_set:
                    new_perm = list(perm)
                    new_perm[i], new_perm[j] = new_perm[j], new_perm[i]
                    neighbors.append(perm_to_tuple(new_perm))
        return neighbors

    target = tuple(range(1, N + 1))
    initial = perm_to_tuple(permutation)

    if initial == target:
        return 0

    allowed_swaps_set = set((min(a, b), max(a, b)) for a, b in allowed_swaps)
    visited = set()
    queue = deque([(initial, 0)])

    while queue:
        current_perm, swaps = queue.popleft()

        if current_perm == target:
            return swaps

        for neighbor in get_neighbors(current_perm):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, swaps + 1))

    return -1

